static inline const MeshcoreBitmapGlyph* meshcoreFindGlyph(const MeshcoreBitmapFont* font, uint16_t codepoint) {
  if (font == NULL) return NULL;
  int lo = 0;
  int hi = (int)font->glyphCount - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    uint16_t cp = font->glyphs[mid].codepoint;
    if (cp == codepoint) return &font->glyphs[mid];
    if (cp < codepoint) lo = mid + 1;
    else hi = mid - 1;
  }
  return NULL;
}
